-- Additive foundation. Business timestamps are ISO-8601 UTC; source values stay separate.
PRAGMA foreign_keys = ON;
CREATE TABLE auth_user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE auth_session (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE);
CREATE INDEX auth_session_user ON auth_session(userId);
CREATE TABLE auth_account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES auth_user(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, UNIQUE(providerId, accountId));
CREATE TABLE auth_verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX auth_verification_identifier ON auth_verification(identifier);
CREATE TABLE auth_rate_limit (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, count INTEGER NOT NULL, lastRequest INTEGER NOT NULL);

CREATE TABLE users (id TEXT PRIMARY KEY, email TEXT, name TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, source_created_at TEXT, source_updated_at TEXT, legacy_id TEXT UNIQUE);
CREATE TABLE auth_identities (issuer TEXT NOT NULL CHECK(issuer = 'email-password'), subject TEXT NOT NULL REFERENCES auth_user(id), user_id TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, PRIMARY KEY(issuer, subject), UNIQUE(user_id, issuer));
CREATE TRIGGER auth_identity_immutable BEFORE UPDATE ON auth_identities BEGIN SELECT RAISE(ABORT, 'immutable_identity'); END;
CREATE TABLE candidate_profiles (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), revision INTEGER NOT NULL DEFAULT 1 CHECK(revision > 0), name TEXT NOT NULL, content_json TEXT NOT NULL CHECK(json_valid(content_json)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, source_created_at TEXT, source_updated_at TEXT, legacy_id TEXT UNIQUE, UNIQUE(id,user_id));
CREATE TABLE profile_versions (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, user_id TEXT NOT NULL, revision INTEGER NOT NULL, name TEXT NOT NULL, content_json TEXT NOT NULL CHECK(json_valid(content_json)), created_at TEXT NOT NULL, UNIQUE(profile_id,revision), UNIQUE(id,profile_id,user_id), FOREIGN KEY(profile_id,user_id) REFERENCES candidate_profiles(id,user_id));
CREATE TRIGGER profile_version_immutable BEFORE UPDATE ON profile_versions BEGIN SELECT RAISE(ABORT, 'immutable_version'); END;
CREATE TABLE active_profiles (user_id TEXT PRIMARY KEY REFERENCES users(id), profile_id TEXT NOT NULL, FOREIGN KEY(profile_id,user_id) REFERENCES candidate_profiles(id,user_id));
CREATE TABLE jobs (id TEXT PRIMARY KEY, title TEXT NOT NULL, company TEXT, location TEXT, remote TEXT, employment TEXT, seniority TEXT, source_url TEXT, description TEXT, status TEXT, revision INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, source_created_at TEXT, source_updated_at TEXT, legacy_id TEXT UNIQUE);
CREATE INDEX jobs_order ON jobs(created_at DESC,id DESC);
CREATE TABLE job_versions (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), revision INTEGER NOT NULL, content_json TEXT NOT NULL CHECK(json_valid(content_json)), created_at TEXT NOT NULL, UNIQUE(job_id,revision));
CREATE TRIGGER job_version_immutable BEFORE UPDATE ON job_versions BEGIN SELECT RAISE(ABORT, 'immutable_version'); END;
CREATE TABLE job_sources (id TEXT PRIMARY KEY, job_id TEXT NOT NULL REFERENCES jobs(id), source_system TEXT NOT NULL, source_key TEXT NOT NULL, source_url TEXT, first_seen_at TEXT, last_seen_at TEXT, UNIQUE(source_system,source_key));
CREATE TABLE saved_jobs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), job_id TEXT NOT NULL REFERENCES jobs(id), revision INTEGER NOT NULL DEFAULT 1, notes TEXT, priority TEXT CHECK(priority IS NULL OR priority IN ('Low','Medium','High')), status TEXT CHECK(status IS NULL OR status IN ('Saved','Draft Requested','Draft Ready','Submitted','Rejected','Offer','Archived')), outcome_notes TEXT, submission_url TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, source_created_at TEXT, source_updated_at TEXT, legacy_id TEXT UNIQUE, UNIQUE(user_id,job_id), UNIQUE(id,user_id));
CREATE INDEX saved_jobs_owner ON saved_jobs(user_id,updated_at DESC,id DESC);
CREATE TABLE draft_applications (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), saved_job_id TEXT NOT NULL, profile_id TEXT, profile_version_id TEXT, revision INTEGER NOT NULL DEFAULT 1, status TEXT CHECK(status IS NULL OR status IN ('In Progress','Ready for Review','Approved','Needs Edits')), execution_status TEXT NOT NULL DEFAULT 'legacy' CHECK(execution_status IN ('legacy','queued','running','succeeded','failed','cancelled')), cover_letter TEXT, short_answers TEXT, reviewer_notes TEXT, approved_revision INTEGER, provenance TEXT NOT NULL DEFAULT 'legacy', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, source_created_at TEXT, source_updated_at TEXT, legacy_id TEXT UNIQUE, UNIQUE(id,user_id), FOREIGN KEY(saved_job_id,user_id) REFERENCES saved_jobs(id,user_id), FOREIGN KEY(profile_id,user_id) REFERENCES candidate_profiles(id,user_id), FOREIGN KEY(profile_version_id,profile_id,user_id) REFERENCES profile_versions(id,profile_id,user_id), CHECK((profile_id IS NULL) = (profile_version_id IS NULL)));
CREATE INDEX drafts_owner_save ON draft_applications(user_id,saved_job_id,updated_at DESC,id DESC);
CREATE TABLE draft_versions (id TEXT PRIMARY KEY, draft_id TEXT NOT NULL, user_id TEXT NOT NULL, revision INTEGER NOT NULL, cover_letter TEXT, short_answers TEXT, reviewer_notes TEXT, status TEXT, created_at TEXT NOT NULL, UNIQUE(draft_id,revision), FOREIGN KEY(draft_id,user_id) REFERENCES draft_applications(id,user_id));
CREATE TRIGGER draft_version_immutable BEFORE UPDATE ON draft_versions BEGIN SELECT RAISE(ABORT, 'immutable_version'); END;
CREATE TABLE attachments (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), profile_id TEXT, draft_id TEXT, object_key TEXT UNIQUE, filename TEXT, media_type TEXT, size_bytes INTEGER CHECK(size_bytes IS NULL OR size_bytes>=0), checksum_sha256 TEXT, status TEXT NOT NULL CHECK(status IN ('missing','pending','available','rejected')), scan_status TEXT NOT NULL CHECK(scan_status IN ('pending','clean','rejected','unknown')), created_at TEXT NOT NULL, source_created_at TEXT, source_updated_at TEXT, legacy_id TEXT UNIQUE, UNIQUE(id,user_id), FOREIGN KEY(profile_id,user_id) REFERENCES candidate_profiles(id,user_id), FOREIGN KEY(draft_id,user_id) REFERENCES draft_applications(id,user_id), CHECK(status != 'available' OR (object_key IS NOT NULL AND checksum_sha256 IS NOT NULL AND size_bytes IS NOT NULL)));
CREATE TABLE generation_requests (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), saved_job_id TEXT NOT NULL, profile_id TEXT NOT NULL, profile_version_id TEXT NOT NULL, idempotency_key TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('queued','running','succeeded','failed','cancelled')), workflow_id TEXT UNIQUE, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(user_id,idempotency_key), FOREIGN KEY(saved_job_id,user_id) REFERENCES saved_jobs(id,user_id), FOREIGN KEY(profile_version_id,profile_id,user_id) REFERENCES profile_versions(id,profile_id,user_id));
CREATE TABLE ingestion_runs (id TEXT PRIMARY KEY, source TEXT NOT NULL, chicago_date TEXT NOT NULL, state TEXT NOT NULL, snapshot_complete INTEGER NOT NULL DEFAULT 0 CHECK(snapshot_complete IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(source,chicago_date));
CREATE TABLE outbox (id TEXT PRIMARY KEY, kind TEXT NOT NULL, aggregate_id TEXT NOT NULL, idempotency_key TEXT NOT NULL UNIQUE, state TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, available_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, actor_user_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, revision INTEGER, created_at TEXT NOT NULL);
CREATE TABLE import_manifests (id TEXT PRIMARY KEY, source_system TEXT NOT NULL, source_hash TEXT NOT NULL, schema_version TEXT NOT NULL, state TEXT NOT NULL, counts_json TEXT NOT NULL CHECK(json_valid(counts_json)), created_at TEXT NOT NULL, UNIQUE(source_system,source_hash));
CREATE TABLE legacy_id_map (source_system TEXT NOT NULL, source_table TEXT NOT NULL, source_id TEXT NOT NULL, target_table TEXT NOT NULL, target_id TEXT NOT NULL, manifest_id TEXT NOT NULL REFERENCES import_manifests(id), source_created_at TEXT, source_updated_at TEXT, PRIMARY KEY(source_system,source_table,source_id));
